// Generated by fluxora generate (Rebuild). Change orchestrator/templates, not this file.
// UI test: one test per reference case. Each fills the migrated form in a real browser, submits it
// to the real migrated API and checks what the page shows. Expected values are read from
// fixtures/claim-triage/reference-cases.json (confirmed by the Power Fx engine), never written here.
import { existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { expect, test, type Page } from "@playwright/test";

interface ReferenceCase {
  id: string;
  ruleIds: string[];
  description: string;
  inputs: Record<string, string | number | boolean | null>;
  expected: { errors: string[]; excess: number | null; payable: number | null; lateReport: boolean | null; status: string | null };
}

const FORM_FIELDS = ["claimId", "policyNumber", "claimType", "policyStartDate", "incidentDate", "reportedDate", "claimAmount", "hasReceipt"];

function casesPath(): string {
  if (process.env.FLUXORA_CASES) return resolve(process.env.FLUXORA_CASES);
  // Works from generated/web and from runs/<run-id>/generated/web.
  let dir = dirname(fileURLToPath(import.meta.url));
  for (;;) {
    const candidate = join(dir, "fixtures", "claim-triage", "reference-cases.json");
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) throw new Error("reference-cases.json not found: set FLUXORA_CASES to its path");
    dir = parent;
  }
}

const cases: ReferenceCase[] = JSON.parse(readFileSync(casesPath(), "utf-8")).cases;
const realToday = new Date().toISOString().slice(0, 10);

// Same formatting as the form (src/App.tsx).
const money = (value: number | null) =>
  value === null ? "-" : value.toLocaleString("en-GB", { style: "currency", currency: "GBP" });

function whyNotInTheForm(c: ReferenceCase, typeOptions: string[]): string | null {
  const type = c.inputs.claimType;
  if (type !== null && !typeOptions.includes(String(type))) {
    return `claim type "${type}" is not in the form's drop-down (Parity Court checks it through the API)`;
  }
  const incident = String(c.inputs.incidentDate);
  if (incident > String(c.inputs.today) || incident > realToday) {
    return "the result depends on Today(); the form uses the real date, the case fixes it (Parity Court checks it with asOf)";
  }
  return null;
}

async function fill(page: Page, inputs: ReferenceCase["inputs"]) {
  for (const name of FORM_FIELDS) {
    const control = page.locator(`#f-${name}`);
    const value = inputs[name];
    if (name === "hasReceipt") await control.setChecked(Boolean(value));
    else if (name === "claimType") await control.selectOption(value === null ? "" : String(value));
    else await control.fill(value === null ? "" : String(value));
  }
}

const shown = (page: Page, label: string) =>
  page.locator("section.result dt", { hasText: new RegExp(`^${label}$`) }).locator("xpath=following-sibling::dd[1]");

for (const c of cases) {
  test(`${c.id} ${c.ruleIds.join(",")}: ${c.description}`, async ({ page }) => {
    await page.goto("/");
    const typeOptions = (await page.locator("#f-claimType option").allTextContents()).filter((o) => o !== "(choose)");
    const reason = whyNotInTheForm(c, typeOptions);
    test.skip(reason !== null, reason ?? "");

    await fill(page, c.inputs);
    await page.getByRole("button", { name: /submit/i }).click();
    await expect(page.locator("section.result")).toBeVisible();

    const e = c.expected;
    await expect(page.locator("section.result ul.errors span.rule")).toHaveText(e.errors);
    await expect(shown(page, "Status")).toHaveText(e.status ?? "-");
    await expect(shown(page, "Excess")).toHaveText(money(e.excess));
    await expect(shown(page, "Payable")).toHaveText(money(e.payable));
    await expect(shown(page, "Late report")).toHaveText(e.lateReport === null ? "-" : e.lateReport ? "Yes" : "No");
  });
}
